// Package config loads the two control files that live at the root of a
// crew directory:
//
//	harnesses.yaml — facts about each harness (paths, formats, tool names,
//	                 which model catalog it draws from).
//	models.yaml    — the baseline list: every model each harness can run,
//	                 its effort levels and prices (generated by `crew models sync`).
//	crew.yaml   — your choices (which harnesses are on, which agents
//	                 each one receives).
//
// All three are decoded strictly: unknown keys are errors.
package config

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"

	"gopkg.in/yaml.v3"
)

const (
	RegistryFile  = "harnesses.yaml"
	ModelsFile    = "models.yaml"
	CrewFile      = "crew.yaml"
	SchemaVersion = 1
)

// ---------- harnesses.yaml ----------

type Registry struct {
	Version        int                `yaml:"version"`
	Verified       string             `yaml:"verified"` // YYYY-MM-DD the facts were last checked
	StaleAfterDays int                `yaml:"stale_after_days"`
	Capabilities   []string           `yaml:"capabilities"`   // agnostic capability vocabulary
	CatalogSource  string             `yaml:"catalog_source"` // URL `crew models sync` fetches
	Harnesses      map[string]Harness `yaml:"harnesses"`
}

type Harness struct {
	Display      string              `yaml:"display"`
	Docs         []string            `yaml:"docs"`
	Catalog      *CatalogSpec        `yaml:"catalog"` // nil = no model choice; agents use "inherit"
	Skills       SkillsSpec          `yaml:"skills"`
	Agents       AgentsSpec          `yaml:"agents"`
	Capabilities map[string][]string `yaml:"capabilities"` // capability → native tool names
	Rules        Rules               `yaml:"rules"`
	Notes        string              `yaml:"notes"`
	Deny         DenySpec            `yaml:"deny"`     // rules every session crew starts must carry; needs headless.deny_via
	Headless     *HeadlessSpec       `yaml:"headless"` // how crew run starts one agent non-interactively; nil = can't run stations
	Foreman      *ForemanSpec        `yaml:"foreman"`  // can host a factory's foreman as the main session; nil = no foremen
}

// ForemanSpec says how a harness hosts a foreman agent as its main session.
type ForemanSpec struct {
	Static map[string]any `yaml:"static"` // keys that override agents.static for foremen (e.g. mode: primary)
	Launch string         `yaml:"launch"` // how the user starts it; {name} is the foreman's name

	OrchestratorLaunch string   `yaml:"orchestrator_launch"` // how the user starts the orchestrator; {name} and {settings}
	Allow              []string `yaml:"orchestrator_allow"`  // native allow rules for the orchestrator's session
}

// DenySpec lists native deny-rule strings for a harness.
type DenySpec struct {
	All      []string `yaml:"all"`      // native rule strings for every session; {crew_dir} is expanded
	Stations []string `yaml:"stations"` // extra rules for stations and headless orchestrator calls
}

// HeadlessSpec is the command crew run uses to run one station. Tokens in
// Command: {agent}, {prompt}, {allowed}, {settings}.
type HeadlessSpec struct {
	Command   []string `yaml:"command"`
	PromptVia string   `yaml:"prompt_via"` // "stdin" | "arg"
	AllowVia  string   `yaml:"allow_via"`  // "flag" ({allowed} token) | "agent-file" (compiled tools list restricts)
	AllowJoin string   `yaml:"allow_join"` // separator for {allowed}; default ","
	DenyVia   string   `yaml:"deny_via"`   // "settings-file" ({settings} token) | "" (this harness can't apply deny rules)
	Output    string   `yaml:"output"`     // "text" (default: stdout is the reply) | "claude-json" (result + permission_denials)
}

// CatalogSpec says which models.dev providers a harness can run and how it
// spells a model id in an agent file.
type CatalogSpec struct {
	Providers []string `yaml:"providers"` // models.dev provider ids, e.g. anthropic, opencode-go
	IDStyle   string   `yaml:"id_style"`  // "model" (claude-opus-5-5) | "provider/model" (opencode-go/kimi-k3)
}

type SkillsSpec struct {
	UserDir    string `yaml:"user_dir"`
	ProjectDir string `yaml:"project_dir"` // relative to --project
	Layout     string `yaml:"layout"`      // "dir" (<name>/SKILL.md) or "flat" (<name>.md)
	// SharesWith lists other harnesses whose skill dirs this harness already
	// loads. If any of them is enabled, skills are not written for this one
	// (avoids duplicate-skill warnings in harnesses like OpenCode).
	SharesWith []string `yaml:"shares_with"`
}

type AgentsSpec struct {
	Supported  bool           `yaml:"supported"`
	UserDir    string         `yaml:"user_dir"`
	ProjectDir string         `yaml:"project_dir"`
	Format     string         `yaml:"format"` // "markdown" | "toml"
	Ext        string         `yaml:"ext"`
	Fields     AgentFields    `yaml:"fields"`
	Static     map[string]any `yaml:"static"`  // constant keys written into every agent
	Derived    []Derived      `yaml:"derived"` // keys computed from capabilities
}

// AgentFields maps crew concepts to the harness's own key names.
// An empty string means "this harness has no such field — don't emit it".
type AgentFields struct {
	Name         string      `yaml:"name"`
	Description  string      `yaml:"description"`
	Model        string      `yaml:"model"`
	Effort       string      `yaml:"effort"`        // key that receives the effort
	EffortSuffix string      `yaml:"effort_suffix"` // or: append effort to the model value after this separator ("#")
	Skills       string      `yaml:"skills"`
	Body         string      `yaml:"body"` // toml only: key that receives the prompt body
	Tools        *ToolsField `yaml:"tools"`
}

type ToolsField struct {
	Key   string `yaml:"key"`
	Style string `yaml:"style"` // "csv" | "list" | "map"
}

type Derived struct {
	Key   string   `yaml:"key"`
	IfAny []string `yaml:"if_any"` // capabilities
	Then  any      `yaml:"then"`
	Else  any      `yaml:"else"` // nil = omit key when condition false
}

type Rules struct {
	NameMax        int      `yaml:"name_max"`
	NameForbidden  []string `yaml:"name_forbidden"` // substrings
	DescriptionMax int      `yaml:"description_max"`
}

// ---------- crew.yaml ----------

type Crew struct {
	Version int               `yaml:"version"`
	Targets map[string]Target `yaml:"targets"`
}

type Target struct {
	Enabled *bool    `yaml:"enabled"`
	Agents  []string `yaml:"agents"`  // names or globs; "*" = all
	Exclude []string `yaml:"exclude"` // names or globs
}

func (t Target) IsEnabled() bool { return t.Enabled != nil && *t.Enabled }

// ---------- loading ----------

func LoadRegistry(dir string) (*Registry, error) {
	var r Registry
	if err := decodeStrict(filepath.Join(dir, RegistryFile), &r); err != nil {
		return nil, err
	}
	return &r, nil
}

func LoadCrew(dir string) (*Crew, error) {
	var l Crew
	if err := decodeStrict(filepath.Join(dir, CrewFile), &l); err != nil {
		return nil, err
	}
	return &l, nil
}

func LoadModels(dir string) (*Models, error) {
	var m Models
	if err := decodeStrict(filepath.Join(dir, ModelsFile), &m); err != nil {
		return nil, err
	}
	return &m, nil
}

var typeName = regexp.MustCompile(`field (\S+) not found in type \S+`)

func decodeStrict(path string, out any) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return decodeStrictBytes(filepath.Base(path), b, out)
}

// DecodeRegistry decodes harnesses.yaml content that isn't on disk (yet) with
// the same strict rules as LoadRegistry. name is used in error messages.
func DecodeRegistry(name string, b []byte) (*Registry, error) {
	var r Registry
	if err := decodeStrictBytes(name, b, &r); err != nil {
		return nil, err
	}
	return &r, nil
}

func decodeStrictBytes(name string, b []byte, out any) error {
	dec := yaml.NewDecoder(bytes.NewReader(b))
	dec.KnownFields(true)
	if err := dec.Decode(out); err != nil {
		if errors.Is(err, io.EOF) {
			return fmt.Errorf("%s: file is empty", name)
		}
		return fmt.Errorf("%s: %s", name, typeName.ReplaceAllString(err.Error(), "unknown key $1"))
	}
	// Reject multi-document files: a stray second document is almost always a mistake.
	var extra any
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		return fmt.Errorf("%s: multiple YAML documents are not allowed", name)
	}
	return nil
}
